const test = require('node:test')
const assert = require('node:assert')
const { EventsEngine } = require('../index')

const createMockDb = () => {
  let events = []
  let replayStates = {}

  const saveEvent = async (event) => {
    if (!events.some(e => e.id === event.id)) {
      events.push(event)
      events.sort((a, b) => a.id.localeCompare(b.id))
    }
  }

  const getEventsFrom = async (id) => {
    return events.filter(e => e.id >= id)
  }

  const getEventsSince = async (id, limit = 100) => {
    const filtered = events.filter(e => e.id > id)
    return filtered.slice(0, limit)
  }

  const runTransaction = async (fn) => {
    return fn() // Sync/Async mock execution
  }

  const saveReplayState = async ({ id, lastProcessedId, context }) => {
    replayStates[id] = { lastProcessedId, context }
  }

  const getReplayState = async (id) => {
    return replayStates[id] || null
  }

  const deleteReplayState = async (id) => {
    delete replayStates[id]
  }

  return {
    saveEvent,
    getEventsFrom,
    getEventsSince,
    runTransaction,
    saveReplayState,
    getReplayState,
    deleteReplayState,
    _getRawEvents: () => events,
  }
}

test('EventsEngine - Ingress and Idempotency', async () => {
  const db = createMockDb()
  const projectionCalls = []
  const effectCalls = []

  const engine = EventsEngine({
    projections: {
      'test.event': async (event) => {
        projectionCalls.push(event.id)
      },
    },
    effects: {
      'test.event': async (event) => {
        effectCalls.push(event.id)
      },
    },
    db,
  })

  const ev1 = { id: '01', type: 'test.event', version: '1.0.0', payload: { val: 10 } }

  // First Ingress
  await engine.ingress(ev1)
  assert.strictEqual(projectionCalls.length, 1)
  assert.strictEqual(effectCalls.length, 1)
  assert.strictEqual(projectionCalls[0], '01')
  assert.strictEqual(effectCalls[0], '01')

  // Second Ingress (Idempotent ignore)
  await engine.ingress(ev1)
  assert.strictEqual(projectionCalls.length, 1) // No new projection calls
  assert.strictEqual(effectCalls.length, 1) // No new side-effect calls
})

test('EventsEngine - Out-of-Order Ingress and Roll-Forward', async () => {
  const db = createMockDb()
  const projectionLogs = []
  const effectLogs = []

  const engine = EventsEngine({
    projections: {
      'test.event': async (event) => {
        projectionLogs.push(`proj:${event.id}`)
      },
    },
    effects: {
      'test.event': async (event) => {
        effectLogs.push(`effect:${event.id}`)
      },
    },
    db,
  })

  // 1. Ingress event A ('01') and event C ('03')
  const evA = { id: '01', type: 'test.event', version: '1.0.0', payload: {} }
  const evC = { id: '03', type: 'test.event', version: '1.0.0', payload: {} }

  await engine.ingress(evA)
  await engine.ingress(evC)

  assert.deepStrictEqual(projectionLogs, ['proj:01', 'proj:03'])
  assert.deepStrictEqual(effectLogs, ['effect:01', 'effect:03'])

  // Clear logs to focus on out-of-order ingress
  projectionLogs.length = 0
  effectLogs.length = 0

  // 2. Ingress event B ('02') out of order (chronologically between A and C)
  const evB = { id: '02', type: 'test.event', version: '1.0.0', payload: {} }
  await engine.ingress(evB)

  // Assertions:
  // - Projections must run for B ('02') then C ('03') in strict order to rebuild state.
  // - Side effects must ONLY run for B ('02') and NEVER be re-run for C ('03').
  assert.deepStrictEqual(projectionLogs, ['proj:02', 'proj:03'])
  assert.deepStrictEqual(effectLogs, ['effect:02'])
})

test('EventsEngine - Chunked, Context-Aware Replay', async () => {
  const db = createMockDb()
  const projectionCalls = []
  const effectCalls = []

  // Seed db with 5 events
  for (let i = 1; i <= 5; i++) {
    await db.saveEvent({ id: `0${i}`, type: 'test.event', version: '1.0.0', payload: {} })
  }

  const engine = EventsEngine({
    projections: {
      'test.event': async (event, { context }) => {
        projectionCalls.push({ id: event.id, scope: context.scope })
      },
    },
    effects: {
      'test.event': async (event, { context }) => {
        effectCalls.push({ id: event.id, scope: context.scope })
      },
    },
    db,
  })

  // Run replay with custom scope context
  await engine.replay({
    context: { scope: 'web-admin' },
  })

  // Verify all 5 events were replayed sequentially with context passed through
  assert.strictEqual(projectionCalls.length, 5)
  assert.strictEqual(effectCalls.length, 5)
  assert.strictEqual(projectionCalls[0].scope, 'web-admin')
  assert.strictEqual(projectionCalls[4].id, '05')
})

test('EventsEngine - Resume Interrupted Replay with Continuation Hook', async () => {
  const db = createMockDb()
  const projectionCalls = []

  // Seed DB with 4 events
  for (let i = 1; i <= 4; i++) {
    await db.saveEvent({ id: `0${i}`, type: 'test.event', version: '1.0.0', payload: {} })
  }

  // Pre-seed an interrupted replay state. Replay stopped after event '02'.
  await db.saveReplayState({
    id: 'resumable-replay',
    lastProcessedId: '02',
    context: { originalMode: 'safe' },
  })

  let continuationHookCalled = false

  const engine = EventsEngine({
    db,
    onReplayContinue: async ({ fromId, context, replayId }) => {
      continuationHookCalled = true
      assert.strictEqual(fromId, '02')
      assert.strictEqual(context.originalMode, 'safe')
      assert.strictEqual(replayId, 'resumable-replay')

      // Return explicit dynamic projections for the continuation session
      return {
        projections: {
          'test.event': async (event, { context: runContext }) => {
            projectionCalls.push(`resumed:${event.id}:${runContext.originalMode}`)
          },
        },
        effects: {},
      }
    },
  })

  // Start replay (will auto-detect saved state, resume from '02', and load continuation)
  await engine.replay({ replayId: 'resumable-replay' })

  assert.strictEqual(continuationHookCalled, true)
  // Should have replayed '03' and '04' using resumed dynamic projections
  assert.deepStrictEqual(projectionCalls, [
    'resumed:03:safe',
    'resumed:04:safe',
  ])

  // Verify the checkpoint state was cleanly deleted upon successful completion
  const activeState = await db.getReplayState('resumable-replay')
  assert.strictEqual(activeState, null)
})

test('EventsEngine - Ephemeral events (persisted: false) do not store to DB but trigger active streams', async () => {
  const db = createMockDb()
  const receivedLogs = []

  const engine = EventsEngine({
    db,
  })

  await engine.subscribeActive({
    predicate: 'node.log.emitted',
    onEvent: (event) => {
      receivedLogs.push(event.payload.message)
    },
  })

  const logResult = await engine.ingress({
    type: 'node.log.emitted',
    version: '1.0.0',
    payload: { nodeId: 'test-node', message: 'Hello ephemeral world' },
  })

  assert.strictEqual(logResult.persisted, false)
  assert.strictEqual(receivedLogs.length, 1)
  assert.strictEqual(receivedLogs[0], 'Hello ephemeral world')

  const storedEvents = await db.getEventsFrom('')
  assert.strictEqual(storedEvents.length, 0)
})
